public interface TunarEngineInterface {
    
    /**
     * 完整分析帧：feed 事件 + 频谱 + 泛音 + 和弦（v4 新增，UniFFI 边界允许分配）。
     */
    fun `analyze`(`pcm`: List<kotlin.Float>): AnalysisFrame
    
    /**
     * 输入一帧单声道 PCM（f32 [-1,1]，长度 ≥ 2048），返回音高事件；无效输入返回 None。
     */
    fun `feed`(`pcm`: List<kotlin.Float>): TunarEvent?
    
    /**
     * 列出当前 A4 与平均律在 80–1500Hz 内的全部固定音高。
     */
    fun `listReferenceTones`(): List<ReferenceTone>
    
    /**
     * 设置 A4 校准（收敛到 415–466Hz）。
     */
    fun `setA4`(`hz`: kotlin.Double)
    
    /**
     * 设置噪声门限（dBFS）。
     */
    fun `setNoiseGate`(`dbfs`: kotlin.Float)
    
    /**
     * 设置唱名体系与调式。
     */
    fun `setSolfege`(`system`: SolfegeSystem, `key`: KeyMode)
    
    /**
     * 设置律制（N ∈ {12,19,24,31}；非法值忽略）。
     */
    fun `setTemperament`(`divisions`: kotlin.UByte)
    
    companion object
}

/**
 * 调音器引擎（UniFFI 对象）。
 */
open class TunarEngine: Disposable, AutoCloseable, TunarEngineInterface
{

    constructor(pointer: Pointer) {
        this.pointer = pointer
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }

    /**
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noPointer: NoPointer) {
        this.pointer = null
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(pointer))
    }
    /**
     * 构造。`config.a4_hz` 越界时收敛到 415–466。
     */
    constructor(`config`: TunarConfig) :
        this(
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_tunar_core_fn_constructor_tunarengine_new(
        FfiConverterTypeTunarConfig.lower(`config`),_status)
}
    )

    protected val pointer: Pointer?
    protected val cleanable: UniffiCleaner.Cleanable

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithPointer(block: (ptr: Pointer) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the pointer being freed concurrently.
        try {
            return block(this.uniffiClonePointer())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val pointer: Pointer?) : Runnable {
        override fun run() {
            pointer?.let { ptr ->
                uniffiRustCall { status ->
                    UniffiLib.INSTANCE.uniffi_tunar_core_fn_free_tunarengine(ptr, status)
                }
            }
        }
    }

    fun uniffiClonePointer(): Pointer {
        return uniffiRustCall() { status ->
            UniffiLib.INSTANCE.uniffi_tunar_core_fn_clone_tunarengine(pointer!!, status)
        }
    }

    
    /**
     * 完整分析帧：feed 事件 + 频谱 + 泛音 + 和弦（v4 新增，UniFFI 边界允许分配）。
     */override fun `analyze`(`pcm`: List<kotlin.Float>): AnalysisFrame {
            return FfiConverterTypeAnalysisFrame.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_tunar_core_fn_method_tunarengine_analyze(
        it, FfiConverterSequenceFloat.lower(`pcm`),_status)
}
    }
    )
    }
    

    
    /**
     * 输入一帧单声道 PCM（f32 [-1,1]，长度 ≥ 2048），返回音高事件；无效输入返回 None。
     */override fun `feed`(`pcm`: List<kotlin.Float>): TunarEvent? {
            return FfiConverterOptionalTypeTunarEvent.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_tunar_core_fn_method_tunarengine_feed(
        it, FfiConverterSequenceFloat.lower(`pcm`),_status)
}
    }
    )
    }
    

    
    /**
     * 列出当前 A4 与平均律在 80–1500Hz 内的全部固定音高。
     */override fun `listReferenceTones`(): List<ReferenceTone> {
            return FfiConverterSequenceTypeReferenceTone.lift(
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_tunar_core_fn_method_tunarengine_list_reference_tones(
        it, _status)
}
    }
    )
    }
    

    
    /**
     * 设置 A4 校准（收敛到 415–466Hz）。
     */override fun `setA4`(`hz`: kotlin.Double)
        = 
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_tunar_core_fn_method_tunarengine_set_a4(
        it, FfiConverterDouble.lower(`hz`),_status)
}
    }
    
    

    
    /**
     * 设置噪声门限（dBFS）。
     */override fun `setNoiseGate`(`dbfs`: kotlin.Float)
        = 
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_tunar_core_fn_method_tunarengine_set_noise_gate(
        it, FfiConverterFloat.lower(`dbfs`),_status)
}
    }
    
    

    
    /**
     * 设置唱名体系与调式。
     */override fun `setSolfege`(`system`: SolfegeSystem, `key`: KeyMode)
        = 
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_tunar_core_fn_method_tunarengine_set_solfege(
        it, FfiConverterTypeSolfegeSystem.lower(`system`),FfiConverterTypeKeyMode.lower(`key`),_status)
}
    }
    
    

    
    /**
     * 设置律制（N ∈ {12,19,24,31}；非法值忽略）。
     */override fun `setTemperament`(`divisions`: kotlin.UByte)
        = 
    callWithPointer {
    uniffiRustCall() { _status ->
    UniffiLib.INSTANCE.uniffi_tunar_core_fn_method_tunarengine_set_temperament(
        it, FfiConverterUByte.lower(`divisions`),_status)
}
    }
    
    

    

    
    
    companion object
    
}

/**
 * @suppress
 */
public object FfiConverterTypeTunarEngine: FfiConverter<TunarEngine, Pointer> {

    override fun lower(value: TunarEngine): Pointer {
        return value.uniffiClonePointer()
    }

    override fun lift(value: Pointer): TunarEngine {
        return TunarEngine(value)
    }

    override fun read(buf: ByteBuffer): TunarEngine {
        // The Rust code always writes pointers as 8 bytes, and will
        // fail to compile if they don't fit.
        return lift(Pointer(buf.getLong()))
    }

    override fun allocationSize(value: TunarEngine) = 8UL

    override fun write(value: TunarEngine, buf: ByteBuffer) {
        // The Rust code always expects pointers written as 8 bytes,
        // and will fail to compile if they don't fit.
        buf.putLong(Pointer.nativeValue(lower(value)))
    }
}



/**
 * 一次完整分析帧（v4 新增）：feed 事件 + 频谱 + 泛音 + 和弦。
 */
data class AnalysisFrame (
    /**
     * 同 feed 语义（无效输入为 None）。
     */
    var `tuner`: TunarEvent?, 
    /**
     * 64 bin 对数轴 60–2400Hz 幅值（dBFS -80~0）。
     */
    var `spectrumDb`: List<kotlin.Float>, 
    /**
     * 128 bin 对数轴 20Hz–wide_spectrum_max_hz 幅值（dBFS -80~0）。
     */
    var `wideSpectrumDb`: List<kotlin.Float>, 
    /**
     * 全频段实际频率上限（min(20kHz, sample_rate/2)）。
     */
    var `wideSpectrumMaxHz`: kotlin.Double, 
    /**
     * 当前分析窗口 256 列最小值包络。
     */
    var `waveformMin`: List<kotlin.Float>, 
    /**
     * 当前分析窗口 256 列最大值包络。
     */
    var `waveformMax`: List<kotlin.Float>, 
    /**
     * 当前帧末端相对引擎启动时的采样位置。
     */
    var `samplePosition`: kotlin.ULong, 
    /**
     * 实际分析采样率。
     */
    var `sampleRateHz`: kotlin.Double, 
    /**
     * 泛音列（≤8，按幅值降序）。
     */
    var `partials`: List<Partial>, 
    /**
     * 和弦名（如 "Cmaj"），无则为 None。
     */
    var `chord`: kotlin.String?, 
    /**
     * 输入信号状态。
     */
    var `signalState`: SignalState, 
    /**
     * 当前分析窗口的 RMS 电平（dBFS）。
     */
    var `inputLevelDbfs`: kotlin.Float, 
    /**
     * 读数显示强度（0~1）。
     */
    var `displayStrength`: kotlin.Float, 
    /**
     * 当前读数是否来自断音保持。
     */
    var `isHeld`: kotlin.Boolean
) {
    
    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAnalysisFrame: FfiConverterRustBuffer<AnalysisFrame> {
    override fun read(buf: ByteBuffer): AnalysisFrame {
        return AnalysisFrame(
            FfiConverterOptionalTypeTunarEvent.read(buf),
            FfiConverterSequenceFloat.read(buf),
            FfiConverterSequenceFloat.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterSequenceFloat.read(buf),
            FfiConverterSequenceFloat.read(buf),
            FfiConverterULong.read(buf),
            FfiConverterDouble.read(buf),
            FfiConverterSequenceTypePartial.read(buf),
            FfiConverterOptionalString.read(buf),
            FfiConverterTypeSignalState.read(buf),
            FfiConverterFloat.read(buf),
            FfiConverterFloat.read(buf),
            FfiConverterBoolean.read(buf),
        )
    }

    override fun allocationSize(value: AnalysisFrame) = (
            FfiConverterOptionalTypeTunarEvent.allocationSize(value.`tuner`) +
            FfiConverterSequenceFloat.allocationSize(value.`spectrumDb`) +
            FfiConverterSequenceFloat.allocationSize(value.`wideSpectrumDb`) +
            FfiConverterDouble.allocationSize(value.`wideSpectrumMaxHz`) +
            FfiConverterSequenceFloat.allocationSize(value.`waveformMin`) +
            FfiConverterSequenceFloat.allocationSize(value.`waveformMax`) +
            FfiConverterULong.allocationSize(value.`samplePosition`) +
            FfiConverterDouble.allocationSize(value.`sampleRateHz`) +
            FfiConverterSequenceTypePartial.allocationSize(value.`partials`) +
            FfiConverterOptionalString.allocationSize(value.`chord`) +
            FfiConverterTypeSignalState.allocationSize(value.`signalState`) +
            FfiConverterFloat.allocationSize(value.`inputLevelDbfs`) +
            FfiConverterFloat.allocationSize(value.`displayStrength`) +
            FfiConverterBoolean.allocationSize(value.`isHeld`)
    )

    override fun write(value: AnalysisFrame, buf: ByteBuffer) {
            FfiConverterOptionalTypeTunarEvent.write(value.`tuner`, buf)
            FfiConverterSequenceFloat.write(value.`spectrumDb`, buf)
            FfiConverterSequenceFloat.write(value.`wideSpectrumDb`, buf)
            FfiConverterDouble.write(value.`wideSpectrumMaxHz`, buf)
            FfiConverterSequenceFloat.write(value.`waveformMin`, buf)
            FfiConverterSequenceFloat.write(value.`waveformMax`, buf)
            FfiConverterULong.write(value.`samplePosition`, buf)
            FfiConverterDouble.write(value.`sampleRateHz`, buf)
            FfiConverterSequenceTypePartial.write(value.`partials`, buf)
            FfiConverterOptionalString.write(value.`chord`, buf)
            FfiConverterTypeSignalState.write(value.`signalState`, buf)
            FfiConverterFloat.write(value.`inputLevelDbfs`, buf)
            FfiConverterFloat.write(value.`displayStrength`, buf)
            FfiConverterBoolean.write(value.`isHeld`, buf)
    }
}



